*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:         #f8f9fb;
  --color-surface:    #ffffff;
  --color-border:     #e5e7eb;
  --color-text:       #111827;
  --color-text-muted: #6b7280;
  --color-primary:    #6366f1;
  --color-primary-hover: #4f46e5;
  --color-danger:     #dc2626;
  --color-danger-hover: #b91c1c;
  --color-danger-subtle: #fef2f2;
  --color-focus:      #6366f1;
  --radius-sm:  6px;
  --radius-md:  10px;
  --radius-lg:  16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10), 0 2px 6px rgba(0,0,0,.06);
  --shadow-lg: 0 20px 60px rgba(0,0,0,.18), 0 8px 24px rgba(0,0,0,.10);
  --font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

/* ─── Base ───────────────────────────────────────────────────────────── */
body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

a { color: var(--color-primary); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ─── Skip link ──────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 100;
  transition: top .15s;
}
.skip-link:focus { top: .75rem; }

/* ─── Focus ring ─────────────────────────────────────────────────────── */
:focus-visible {
  outline: 2.5px solid var(--color-focus);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ─── Header ─────────────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.site-header__inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-text);
  text-decoration: none;
}
.logo:hover { text-decoration: none; }
.site-header nav ul {
  list-style: none;
  display: flex;
  gap: .25rem;
}
.site-header nav a {
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  color: var(--color-text-muted);
  transition: background .15s, color .15s;
}
.site-header nav a:hover {
  background: var(--color-bg);
  color: var(--color-text);
  text-decoration: none;
}

/* ─── Main ───────────────────────────────────────────────────────────── */
main {
  flex: 1;
  max-width: 1120px;
  width: 100%;
  margin: 0 auto;
  padding: 1.5rem;
}

/* ─── Breadcrumb ─────────────────────────────────────────────────────── */
.breadcrumb { margin-bottom: 1.25rem; }
.breadcrumb ol {
  list-style: none;
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .875rem;
  color: var(--color-text-muted);
}
.breadcrumb a { color: var(--color-text-muted); }
.breadcrumb a:hover { color: var(--color-primary); }
.breadcrumb [aria-current="page"] { color: var(--color-text); font-weight: 500; }

/* ─── Preview card ───────────────────────────────────────────────────── */
.preview-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 320px;
}

.preview-image-wrap {
  background: #0f0f0f;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 480px;
}
.preview-image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  max-height: 600px;
}

/* ─── Meta panel ─────────────────────────────────────────────────────── */
.preview-meta {
  border-left: 1px solid var(--color-border);
  padding: 2rem 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}
.preview-meta__title {
  font-size: 1.05rem;
  font-weight: 600;
  word-break: break-all;
  line-height: 1.4;
}

.meta-list { display: flex; flex-direction: column; gap: .75rem; }
.meta-list__item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .25rem;
  font-size: .875rem;
}
.meta-list__item dt { color: var(--color-text-muted); }
.meta-list__item dd { font-weight: 500; }

.preview-meta__actions {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

/* ─── Buttons ────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .5rem 1rem;
  font: inherit;
  font-size: .875rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s, box-shadow .15s;
  white-space: nowrap;
}
.btn--secondary {
  background: var(--color-surface);
  color: var(--color-text);
  border-color: var(--color-border);
}
.btn--secondary:hover {
  background: var(--color-bg);
  border-color: #d1d5db;
}
.btn--danger {
  background: var(--color-danger);
  color: #fff;
  border-color: var(--color-danger);
}
.btn--danger:hover {
  background: var(--color-danger-hover);
  border-color: var(--color-danger-hover);
}
.btn--primary {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}
.btn--primary:hover {
  background: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

/* ─── Footer ─────────────────────────────────────────────────────────── */
.site-footer {
  text-align: center;
  padding: 1.5rem;
  font-size: .8rem;
  color: var(--color-text-muted);
  border-top: 1px solid var(--color-border);
  margin-top: 3rem;
}

/* ─── Dialog ─────────────────────────────────────────────────────────── */
dialog {
  border: none;
  border-radius: var(--radius-lg);
  padding: 0;
  box-shadow: var(--shadow-lg);
  max-width: 440px;
  width: calc(100% - 2rem);
  background: var(--color-surface);
}

/* Native ::backdrop */
dialog::backdrop {
  background: rgba(0, 0, 0, .45);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

/* Closed state — hidden from AT and focus order */
dialog:not([open]) {
  display: none;
}

.dialog__inner {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1rem;
}

.dialog__icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-danger-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.dialog__heading {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.3;
}

.dialog__body {
  font-size: .9rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog__actions {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  gap: .75rem;
  padding-top: .5rem;
}

/* ─── Reduced motion ─────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; }
}

/* ─── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 720px) {
  .preview-card {
    grid-template-columns: 1fr;
  }
  .preview-meta {
    border-left: none;
    border-top: 1px solid var(--color-border);
  }
  .preview-image-wrap { min-height: 260px; }
  .dialog__actions { flex-direction: column-reverse; }
  .dialog__actions .btn { width: 100%; }
}

@media (max-width: 400px) {
  .preview-meta { padding: 1.25rem; }
  .dialog__inner { padding: 1.5rem; }
}
