const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const html = fs.readFileSync('index.html', 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Test 1: default state (dialog closed)
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Test 2: dialog open state
  await page.evaluate(() => document.getElementById('delete-dialog').showModal());
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const summarise = (r, label) => {
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    return {
      label,
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
      bp:   bp.map(v =>  ({ id: v.id, targets: v.nodes.map(n => n.target) })),
    };
  };

  console.log(JSON.stringify([summarise(r1, 'closed'), summarise(r2, 'open')], null, 2));
  const hasWcag = [...r1.violations, ...r2.violations].some(v => !v.tags.includes('best-practice'));
  process.exit(hasWcag ? 1 : 0);
})();
EOF", 'description': 'Run axe on closed and open dialog states', 'initial_wait': 40}, intention_summary='Run axe on closed and open dialog states', mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.FUNCTION: 'function'>)

